it('characterizes prior released value redaction during cancellation after a later action',async()=>{
 const origin='https://example.test',context=guidedContext(origin),canary='aria-prior-released-value';context.sourceStepIds=['nav','fill','submit'];
 context.authoredInputs.inputs.push({inputId:'pass',sourceStepId:'fill',kind:'secretRef',intendedSlot:'fill.value',secretId:'PASS',provenance:{referenceKind:'configuration',configurationRevision:context.configurationRevision,stepId:'fill',referenceId:'pass-ref',referenceName:'PASS',kind:'secretRef',intendedSlot:'fill.value'}});
