 const directory=await mkdtemp('/tmp/aria-cancel-'),messages:any[]=[],stderr:string[]=[];let generation=0,finishClose:()=>void=()=>{};let runtime:GuidedRuntime;
 const browser:any={evidence:{kind:'initialBlank',sessionId:context.sessionId,contextId:context.contextId,creationId:'creation',bootstrapId:'bootstrap',documentId:'blank',url:'about:blank',origin:null,generation:0},blankMatches:async()=>true,navigateBlank:async()=>{},close:()=>new Promise<void>(resolve=>{finishClose=resolve;}),observations:{withhold:async()=>{},dispose:async()=>{},pageMatches:async()=>true,preparePassword:async()=>{},fillPassword:async()=>{},assertPage:async()=>{void runtime.stop('CANCELLED');throw new Error(canary);},observe:async()=>({observation:{schemaVersion:3,sessionId:context.sessionId,scopeHash:context.scopeHash,documentId:'document',generation:++generation,origin,observedAt:new Date().toISOString(),coverage:{mode:'semantic',complete:false,truncated:false,withheldRegions:1,passwordControls:1,reason:'sensitivity'},nodes:[]},json:'',bytes:0,observationHash:''})}};
 runtime=new GuidedRuntime(context,{workerId:context.workerId,journalDirectory:directory,rules:[],launch:async()=>browser,callback:async(route,body)=>{messages.push({route,body});},diagnosticStderr:text=>stderr.push(text)});
 const perform=async(step:string,operation:any,secret?:any)=>{const previous=messages.filter(m=>m.route==='observations').at(-1)?.body.observation;const evidence=previous?{kind:'observedDocument',sessionId:context.sessionId,contextId:context.contextId,documentId:previous.documentId,generation:previous.generation,origin,observationHash:hash(previous)}:browser.evidence;const p=proposal(context,evidence as any,step,operation,step==='fill'?{kind:'passwordControl',documentId:evidence.documentId,generation:evidence.generation}:undefined);const proof=await runtime.prepare({...identity(context),proposal:p,requestDigest:hash(p),expiresAt:new Date(Date.now()+10000).toISOString()});return runtime.dispatch({...dispatch(context,p,proof),...(secret?{secret}:{})});};
 try{await runtime.start();await perform('nav',{kind:'navigate',destinationInputId:'input-nav'});await perform('fill',{kind:'fill',value:{kind:'secretRef',sourceInputId:'pass'}},{secretId:'PASS',value:canary,versionId:'v1',allowedOrigins:[origin]});const pending=perform('submit',{kind:'assert',predicate:'title',expected:{kind:'authoredLiteral',sourceInputId:'assertion'}});for(let i=0;i<100&&!messages.some(m=>m.route==='outcomes'&&m.body.ledger.coordinate.stepId==='submit');i++)await new Promise(r=>setTimeout(r,5));const outcome=messages.find(m=>m.route==='outcomes'&&m.body.ledger.coordinate.stepId==='submit')?.body;expect(outcome).toBeDefined();const file=(await readdir(directory)).find(f=>f.endsWith('.diagnostic.jsonl'));const persisted=file?await readFile(join(directory,file),'utf8'):'';const result={probe:'prior-secret-cancel',callbackLeaksPriorValue:outcome.errorMessage.includes(canary),stderrLeaksPriorValue:stderr.join('').includes(canary),diagnosticLeaksPriorValue:persisted.includes(canary),browser:'stub',joined:false};facts.push(result);expect(result.callbackLeaksPriorValue).toBe(true);expect(result.stderrLeaksPriorValue).toBe(true);expect(result.diagnosticLeaksPriorValue).toBe(true);finishClose();await pending;}finally{finishClose();await runtime.stop('CANCELLED');await rm(directory,{recursive:true,force:true});await writeFile('/tmp/studio-obs007-aria-probes/facts.json',JSON.stringify(facts,null,2));}
});
